const { subject, body, htmlBody, priority, type, tags } = $.input;
if (!body && !htmlBody) throw new Error('body or htmlBody is required');

const comment = {};
if (htmlBody) comment.html_body = htmlBody;
else comment.body = body;

const ticket = { comment };
if (subject) ticket.subject = subject;
if (priority) ticket.priority = priority;
if (type) ticket.type = type;
if (tags && tags.length) ticket.tags = tags;

return { body: { ticket } };

const resp = $.steps.createTicket.response || {};
const ticket = resp.ticket || {};
return {
  ticketId: ticket.id || '',
  subject: ticket.subject || $.input.subject || '',
  status: ticket.status || '',
  priority: ticket.priority || '',
  url: ticket.url || '',
  createdAt: ticket.created_at || '',
  tags: ticket.tags || [],
  summary: ticket.id ? `Created ticket #${ticket.id}: "${ticket.subject || 'No subject'}" (${ticket.status || 'open'})` : 'Failed to create ticket'
};
